import {
    Table,
    GenericColumn,
    DateTimeColumn,
    ReferenceColumn,
    BooleanColumn,
    ChoiceColumn,
    IntegerColumn,
    OverrideColumn,
} from '../../db'

export const sc_req_item = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    attributes: {
        global_search_config_handler: 'RequestItemSearchConfig',
        hasWorkflow: true,
    },
    audit: true,
    extends: 'task',
    label: 'Requested Item',
    licensingConfig: {
        licenseCondition:
            'requested_forISEMPTY^sys_updated_byNSAMEASrequest.requested_for.user_name^stateNOT IN-5,1^NQrequested_forISNOTEMPTY^sys_updated_byNSAMEASrequest.requested_for.user_name^sys_updated_byNSAMEASrequested_for.user_name^stateNOT IN-5,1^EQ',
    },
    name: 'sc_req_item',
    schema: {
        recurring_price: GenericColumn({
            attributes: {
                serializer: 'com.glide.script.PriceXMLSerializer',
            },
            columnType: 'price',
            default: '0',
            label: 'Recurring Price',
            maxLength: 20,
        }),
        estimated_delivery: DateTimeColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Estimated delivery',
        }),
        cat_item: ReferenceColumn({
            attributes: {
                popup_processor: 'com.glideapp.servicecatalog.CatItemPopper',
                popover: true,
            },
            label: 'Item',
            referenceTable: 'sc_cat_item',
            referenceQual:
                'type!=bundle^sys_class_name!=sc_cat_item_guide^type!=package^sys_class_name!=sc_cat_item_content^EQ',
            useReferenceQualifier: 'simple',
        }),
        price: GenericColumn({
            columnType: 'currency',
            label: 'Price',
            maxLength: 20,
        }),
        billable: BooleanColumn({
            label: 'Billable',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        recurring_frequency: ChoiceColumn({
            dropdown: 'dropdown_with_none',
            dynamicValueDefinitions: {
                type: 'choices_from_other_table',
                table: 'sys_frequency',
                field: 'value',
            },
            label: 'Recurring Price Frequency',
        }),
        requested_for: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
            },
            default: 'javascript:gs.getUserID()',
            label: [
                {
                    hint: 'On behalf of another individual',
                    label: 'Requested for',
                    plural: 'Requested for',
                },
            ],
            referenceTable: 'sys_user',
        }),
        order_guide: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Order Guide',
            referenceTable: 'sc_cat_item_guide',
        }),
        context: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Context',
            referenceTable: 'wf_context',
        }),
        request: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: 'Request',
            referenceTable: 'sc_request',
        }),
        stage: GenericColumn({
            attributes: {
                icons: 'WorkflowIconsSCR',
            },
            columnType: 'workflow',
            default: 'waiting_for_approval',
            choices: {
                waiting_for_approval: {
                    label: 'Waiting for Approval',
                    sequence: 1,
                },
                fulfillment: {
                    label: 'Fulfillment',
                    sequence: 2,
                },
                delivery: {
                    label: 'Delivery',
                    sequence: 3,
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Stage',
            maxLength: 80,
            readOnly: true,
            readOnlyOption: 'strict_read_only',
        }),
        quantity: IntegerColumn({
            default: '1',
            label: 'Quantity',
        }),
        sc_catalog: ReferenceColumn({
            label: 'Catalog',
            readOnly: true,
            readOnlyOption: 'instance_configured',
            referenceTable: 'sc_catalog',
        }),
        configuration_item: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Configuration item',
            referenceTable: 'cmdb_ci',
            referenceQual: 'install_status=6',
            useReferenceQualifier: 'simple',
        }),
        backordered: BooleanColumn({
            label: 'Backordered',
        }),
        flow_context: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                no_text_index: true,
            },
            cascadeRule: 'none',
            label: 'Flow Context',
            referenceTable: 'sys_flow_context',
        }),
        assigned_to: OverrideColumn({
            baseTable: 'task',
            referenceQualifier: 'roles=itil^ORroles=sn_request_write',
        }),
        priority: OverrideColumn({
            baseTable: 'task',
            default: '',
        }),
    },
    textIndex: true,
})
